#![cfg(feature = "c")]

use code_gen::c::*;
use code_gen::*;

/// The comment at the top of a generated file.
const DO_NOT_EDIT: &str = "// DO NOT EDIT: This file was generated by the ProtoPacket compiler.";

/// Creates the signature of the function that encodes a point.
fn point_encode_signature() -> Signature {
    Signature::from("point_encode")
        .with_param(("self", CType::from("point_t").to_const().to_pointer()))
        .with_param(("out", CType::from("uint8_t").to_array("POINT_ENCODED_LEN")))
}

/// Creates the signature of the function that decodes a point.
fn point_decode_signature() -> Signature {
    Signature::from("point_decode")
        .with_result("bool")
        .with_param(("bytes", CType::from("uint8_t").to_const().to_pointer()))
        .with_param(("len", "size_t"))
        .with_param(("out", CType::from("point_t").to_pointer()))
}

#[test]
fn struct_header() {
    let point: Struct = Struct::from("point")
        .with_comment(" A point on a grid.")
        .with_typedef_name("point_t")
        .with_field(StructField::from(("x", "int32_t")).with_comment(" The horizontal position."))
        .with_field(StructField::from(("y", "int32_t")).with_comment(" The vertical position."));

    let new: Function = Function::from(
        Signature::from("point_new")
            .with_result("point_t")
            .with_param(("x", "int32_t"))
            .with_param(("y", "int32_t")),
    )
    .with_comment(" Creates a point.")
    .with_modifier(Modifier::Static)
    .with_modifier(Modifier::Inline)
    .with_semi("return (point_t){.x = x, .y = y}");

    let eq: Function = Function::from(
        Signature::from("point_eq")
            .with_result("bool")
            .with_param(("a", "const point_t *"))
            .with_param(("b", "const point_t *")),
    )
    .with_comment(" Checks if two points are equal.")
    .with_modifier(Modifier::Static)
    .with_modifier(Modifier::Inline)
    .with_semi("return a->x == b->x && a->y == b->y");

    let cmp: Function = Function::from(
        Signature::from("point_cmp")
            .with_result("int")
            .with_param(("a", "const point_t *"))
            .with_param(("b", "const point_t *")),
    )
    .with_comment(" Compares two points, by `x` & then by `y`.")
    .with_modifier(Modifier::Static)
    .with_modifier(Modifier::Inline)
    .with_statement(
        IfStatement::from("a->x != b->x")
            .with_success_statements(Block::default().with_semi("return a->x < b->x ? -1 : 1"))
            .with_else_if(
                "a->y != b->y",
                Block::default().with_semi("return a->y < b->y ? -1 : 1"),
            )
            .with_else_statements(Block::default().with_semi("return 0")),
    );

    let encode: SignatureDec = SignatureDec::from(point_encode_signature())
        .with_comment(" Encodes the point to the `out` bytes.");

    let decode: SignatureDec = SignatureDec::from(point_decode_signature())
        .with_comment(" Decodes the point from the `bytes`.")
        .with_comment("")
        .with_comment(" Returns `false` if the `bytes` are not a valid encoding.");

    let guard: IncludeGuard = IncludeGuard::from("POINT_H")
        .with_statement(Include::from("stdbool.h").with_system(true))
        .with_statement(Include::from("stddef.h").with_system(true))
        .with_statement(Include::from("stdint.h").with_system(true))
        .with_empty_line()
        .with_statement(
            Define::from(("POINT_ENCODED_LEN", "8"))
                .with_comment(" The length of an encoded point, in bytes."),
        )
        .with_empty_line()
        .with_statement(point)
        .with_empty_line()
        .with_statement(new)
        .with_empty_line()
        .with_statement(eq)
        .with_empty_line()
        .with_statement(cmp)
        .with_empty_line()
        .with_statement(encode)
        .with_empty_line()
        .with_statement(decode);

    let code: String = Block::default()
        .with_literal(DO_NOT_EDIT)
        .with_empty_line()
        .with_statement(guard)
        .to_code();

    let expected: &str = r#"// DO NOT EDIT: This file was generated by the ProtoPacket compiler.

#ifndef POINT_H
#define POINT_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/** The length of an encoded point, in bytes. */
#define POINT_ENCODED_LEN 8

/** A point on a grid. */
typedef struct point {
    /** The horizontal position. */
    int32_t x;

    /** The vertical position. */
    int32_t y;
} point_t;

/** Creates a point. */
static inline point_t point_new(int32_t x, int32_t y) {
    return (point_t){.x = x, .y = y};
}

/** Checks if two points are equal. */
static inline bool point_eq(const point_t *a, const point_t *b) {
    return a->x == b->x && a->y == b->y;
}

/** Compares two points, by `x` & then by `y`. */
static inline int point_cmp(const point_t *a, const point_t *b) {
    if (a->x != b->x) {
        return a->x < b->x ? -1 : 1;
    } else if (a->y != b->y) {
        return a->y < b->y ? -1 : 1;
    } else {
        return 0;
    }
}

/** Encodes the point to the `out` bytes. */
void point_encode(const point_t *self, uint8_t out[POINT_ENCODED_LEN]);

/**
 * Decodes the point from the `bytes`.
 *
 * Returns `false` if the `bytes` are not a valid encoding.
 */
bool point_decode(const uint8_t *bytes, size_t len, point_t *out);

#endif // POINT_H
"#;
    assert_eq!(code, expected);
}

#[test]
fn struct_source() {
    let bytes_loop = |statement: &str| -> ForLoop {
        ForLoop::from(("size_t i = 0", "i < 4", "i++")).with_semi(statement)
    };

    let read: Function = Function::from(
        Signature::from("read_i32")
            .with_result("int32_t")
            .with_param(("bytes", "const uint8_t *")),
    )
    .with_comment(" Reads a little-endian `int32_t` from the `bytes`.")
    .with_modifier(Modifier::Static)
    .with_statement(VarInit::from((("value", "uint32_t"), Literal::from("0"))))
    .with_statement(bytes_loop("value |= (uint32_t)bytes[i] << (8 * i)"))
    .with_semi("return (int32_t)value");

    let write: Function = Function::from(
        Signature::from("write_i32")
            .with_param(("out", "uint8_t *"))
            .with_param(("value", "int32_t")),
    )
    .with_comment(" Writes the `value` to the `out` bytes as a little-endian `int32_t`.")
    .with_modifier(Modifier::Static)
    .with_statement(bytes_loop("out[i] = (uint8_t)((uint32_t)value >> (8 * i))"));

    let encode: Function = Function::from(point_encode_signature())
        .with_semi("write_i32(out, self->x)")
        .with_semi("write_i32(out + 4, self->y)");

    let decode: Function = Function::from(point_decode_signature())
        .with_statement(
            IfStatement::from("len != POINT_ENCODED_LEN")
                .with_success_statements(Block::default().with_semi("return false")),
        )
        .with_semi("out->x = read_i32(bytes)")
        .with_semi("out->y = read_i32(bytes + 4)")
        .with_semi("return true");

    let code: String = Block::default()
        .with_literal(DO_NOT_EDIT)
        .with_empty_line()
        .with_statement(Include::from("point.h"))
        .with_empty_line()
        .with_statement(read)
        .with_empty_line()
        .with_statement(write)
        .with_empty_line()
        .with_statement(encode)
        .with_empty_line()
        .with_statement(decode)
        .to_code();

    let expected: &str = r#"// DO NOT EDIT: This file was generated by the ProtoPacket compiler.

#include "point.h"

/** Reads a little-endian `int32_t` from the `bytes`. */
static int32_t read_i32(const uint8_t *bytes) {
    uint32_t value = 0;
    for (size_t i = 0; i < 4; i++) {
        value |= (uint32_t)bytes[i] << (8 * i);
    }
    return (int32_t)value;
}

/** Writes the `value` to the `out` bytes as a little-endian `int32_t`. */
static void write_i32(uint8_t *out, int32_t value) {
    for (size_t i = 0; i < 4; i++) {
        out[i] = (uint8_t)((uint32_t)value >> (8 * i));
    }
}

void point_encode(const point_t *self, uint8_t out[POINT_ENCODED_LEN]) {
    write_i32(out, self->x);
    write_i32(out + 4, self->y);
}

bool point_decode(const uint8_t *bytes, size_t len, point_t *out) {
    if (len != POINT_ENCODED_LEN) {
        return false;
    }
    out->x = read_i32(bytes);
    out->y = read_i32(bytes + 4);
    return true;
}
"#;
    assert_eq!(code, expected);
}

#[test]
fn enumeration() {
    let color: Typedef = Typedef::from(("color_t", "uint16_t"))
        .with_comment(" A color.")
        .with_comment("")
        .with_comment(" Any other value is a tag number the enum doesn't know.");

    let cases: [(&str, &str, &str); 3] = [
        ("COLOR_RED", "1", "Red"),
        ("COLOR_GREEN", "2", "Green"),
        ("COLOR_BLUE", "3", "Blue"),
    ];
    let mut color_case: Enum = Enum::from("color_case").with_comment(" The cases of a color.");
    let mut names: SwitchStatement = SwitchStatement::from("self");
    for (case, tag_number, name) in cases {
        color_case.add_case(
            EnumCase::from(case)
                .with_comment(format!(" The color: `{name}`."))
                .with_value(tag_number),
        );
        names.add_switch_case(
            SwitchCase::from(case)
                .with_semi(format!("return \"{name}\""))
                .with_break(false),
        );
    }
    names.add_switch_case(
        SwitchCase::default()
            .with_semi("return NULL")
            .with_break(false),
    );

    let name: Function = Function::from(
        Signature::from("color_name")
            .with_result(CType::from("char").to_const().to_pointer())
            .with_param(("self", "color_t")),
    )
    .with_comment(" Gets the name of the color. Returns `NULL` if the enum doesn't know it.")
    .with_statement(names);

    let code: String = Block::default()
        .with_statement(color)
        .with_empty_line()
        .with_statement(color_case)
        .with_empty_line()
        .with_statement(name)
        .to_code();

    let expected: &str = r#"/**
 * A color.
 *
 * Any other value is a tag number the enum doesn't know.
 */
typedef uint16_t color_t;

/** The cases of a color. */
enum color_case {
    /** The color: `Red`. */
    COLOR_RED = 1,

    /** The color: `Green`. */
    COLOR_GREEN = 2,

    /** The color: `Blue`. */
    COLOR_BLUE = 3,
};

/** Gets the name of the color. Returns `NULL` if the enum doesn't know it. */
const char *color_name(color_t self) {
    switch (self) {
        case COLOR_RED: {
            return "Red";
        }
        case COLOR_GREEN: {
            return "Green";
        }
        case COLOR_BLUE: {
            return "Blue";
        }
        default: {
            return NULL;
        }
    }
}
"#;
    assert_eq!(code, expected);
}

#[test]
fn variant() {
    let tag: Enum = Enum::from("shape_tag")
        .with_comment(" The tag numbers of the cases of a shape.")
        .with_case(
            EnumCase::from("SHAPE_CIRCLE")
                .with_comment(" A circle.")
                .with_value("1"),
        )
        .with_case(
            EnumCase::from("SHAPE_SQUARE")
                .with_comment(" A square.")
                .with_value("2"),
        );

    let value: Union = Union::from("shape_value")
        .with_comment(" The value of the case of a shape.")
        .with_typedef_name("shape_value_t")
        .with_field(StructField::from(("circle", "circle_t")).with_comment(" A circle."))
        .with_field(StructField::from(("square", "square_t")).with_comment(" A square."))
        .with_field(
            StructField::from(("unrecognized", "pp_bytes_t"))
                .with_comment(" The encoded value of a case the variant doesn't know."),
        );

    let shape: Struct = Struct::from("shape")
        .with_comment(" A shape.")
        .with_typedef_name("shape_t")
        .with_field(
            StructField::from(("tag_number", "uint16_t"))
                .with_comment(" The tag number of the case."),
        )
        .with_field(
            StructField::from(("value", "shape_value_t")).with_comment(" The value of the case."),
        );

    let as_circle: Function = Function::from(
        Signature::from("shape_as_circle")
            .with_result(CType::from("circle_t").to_const().to_pointer())
            .with_param(("self", "const shape_t *")),
    )
    .with_comment(" Gets the value of the case: `Circle`. Returns `NULL` for any other case.")
    .with_statement(
        IfStatement::from("self->tag_number == SHAPE_CIRCLE")
            .with_success_statements(Block::default().with_semi("return &self->value.circle"))
            .with_else_statements(Block::default().with_semi("return NULL")),
    );

    let encode_to: Function = Function::from(
        Signature::from("shape_encode_to")
            .with_param(("self", "const shape_t *"))
            .with_param(("out", "pp_buf_t *")),
    )
    .with_comment(" Appends the encoding of the shape to the `out` bytes.")
    .with_semi("pp_buf_write_u16(out, self->tag_number)")
    .with_statement(
        SwitchStatement::from("self->tag_number")
            .with_switch_case(
                SwitchCase::from("SHAPE_CIRCLE")
                    .with_semi("circle_encode_to(&self->value.circle, out)"),
            )
            .with_switch_case(
                SwitchCase::from("SHAPE_SQUARE")
                    .with_semi("square_encode_to(&self->value.square, out)"),
            )
            .with_switch_case(
                SwitchCase::default().with_semi("pp_buf_write(out, self->value.unrecognized)"),
            ),
    );

    let code: String = Block::default()
        .with_statement(tag)
        .with_empty_line()
        .with_statement(value)
        .with_empty_line()
        .with_statement(shape)
        .with_empty_line()
        .with_statement(as_circle)
        .with_empty_line()
        .with_statement(encode_to)
        .to_code();

    let expected: &str = r#"/** The tag numbers of the cases of a shape. */
enum shape_tag {
    /** A circle. */
    SHAPE_CIRCLE = 1,

    /** A square. */
    SHAPE_SQUARE = 2,
};

/** The value of the case of a shape. */
typedef union shape_value {
    /** A circle. */
    circle_t circle;

    /** A square. */
    square_t square;

    /** The encoded value of a case the variant doesn't know. */
    pp_bytes_t unrecognized;
} shape_value_t;

/** A shape. */
typedef struct shape {
    /** The tag number of the case. */
    uint16_t tag_number;

    /** The value of the case. */
    shape_value_t value;
} shape_t;

/** Gets the value of the case: `Circle`. Returns `NULL` for any other case. */
const circle_t *shape_as_circle(const shape_t *self) {
    if (self->tag_number == SHAPE_CIRCLE) {
        return &self->value.circle;
    } else {
        return NULL;
    }
}

/** Appends the encoding of the shape to the `out` bytes. */
void shape_encode_to(const shape_t *self, pp_buf_t *out) {
    pp_buf_write_u16(out, self->tag_number);
    switch (self->tag_number) {
        case SHAPE_CIRCLE: {
            circle_encode_to(&self->value.circle, out);
            break;
        }
        case SHAPE_SQUARE: {
            square_encode_to(&self->value.square, out);
            break;
        }
        default: {
            pp_buf_write(out, self->value.unrecognized);
            break;
        }
    }
}
"#;
    assert_eq!(code, expected);
}

#[test]
fn view() {
    let getter = |name: &str, value: &str| -> Function {
        Function::from(
            Signature::from(name)
                .with_result("int32_t")
                .with_param(("self", "const void *")),
        )
        .with_modifier(Modifier::Static)
        .with_semi(format!("return {value}"))
    };
    let table = |name: &str, comment: &str, getters: &str| -> ConstInit {
        ConstInit::from(((name, "point_view_t"), Literal::from(getters))).with_comment(comment)
    };

    let mut view: Struct = Struct::from("point_view")
        .with_comment(" The fields of any form of a point.")
        .with_typedef_name("point_view_t");
    for field in ["x", "y"] {
        let getter_pointer: CType = CType::from("int32_t")
            .with_param(("self", "const void *"))
            .to_pointer();
        view.add_field(
            StructField::from((field, getter_pointer))
                .with_comment(format!(" Gets the field: `{field}`.")),
        );
    }

    let encode_to: Function = Function::from(
        Signature::from("point_view_encode_to")
            .with_param(("view", "const point_view_t *"))
            .with_param(("self", "const void *"))
            .with_param(("out", "pp_buf_t *")),
    )
    .with_comment(" Appends the encoding of any form of a point to the `out` bytes.")
    .with_semi("pp_buf_write_i32(out, view->x(self))")
    .with_semi("pp_buf_write_i32(out, view->y(self))");

    let code: String = Block::default()
        .with_statement(view)
        .with_empty_line()
        .with_statement(getter("point_x", "((const point_t *)self)->x"))
        .with_empty_line()
        .with_statement(getter("point_y", "((const point_t *)self)->y"))
        .with_empty_line()
        .with_statement(table(
            "POINT_VIEW",
            " The view of a point.",
            "{.x = point_x, .y = point_y}",
        ))
        .with_empty_line()
        .with_statement(getter("point_ref_x", "pp_read_i32(self, 0)"))
        .with_empty_line()
        .with_statement(getter("point_ref_y", "pp_read_i32(self, 4)"))
        .with_empty_line()
        .with_statement(table(
            "POINT_REF_VIEW",
            " The view of an encoded point.",
            "{.x = point_ref_x, .y = point_ref_y}",
        ))
        .with_empty_line()
        .with_statement(encode_to)
        .to_code();

    let expected: &str = r#"/** The fields of any form of a point. */
typedef struct point_view {
    /** Gets the field: `x`. */
    int32_t (*x)(const void *self);

    /** Gets the field: `y`. */
    int32_t (*y)(const void *self);
} point_view_t;

static int32_t point_x(const void *self) {
    return ((const point_t *)self)->x;
}

static int32_t point_y(const void *self) {
    return ((const point_t *)self)->y;
}

/** The view of a point. */
static const point_view_t POINT_VIEW = {.x = point_x, .y = point_y};

static int32_t point_ref_x(const void *self) {
    return pp_read_i32(self, 0);
}

static int32_t point_ref_y(const void *self) {
    return pp_read_i32(self, 4);
}

/** The view of an encoded point. */
static const point_view_t POINT_REF_VIEW = {.x = point_ref_x, .y = point_ref_y};

/** Appends the encoding of any form of a point to the `out` bytes. */
void point_view_encode_to(const point_view_t *view, const void *self, pp_buf_t *out) {
    pp_buf_write_i32(out, view->x(self));
    pp_buf_write_i32(out, view->y(self));
}
"#;
    assert_eq!(code, expected);
}

#[test]
fn service() {
    let greet: CType = CType::from("pp_status_t")
        .with_param(("context", "void *"))
        .with_param(("request", "const greet_request_t *"))
        .with_param(("response", "greet_response_t *"))
        .to_pointer();
    let greeter: Struct = Struct::from("greeter")
        .with_comment(" A greeter.")
        .with_typedef_name("greeter_t")
        .with_field(
            StructField::from(("context", "void *"))
                .with_comment(" The state that is passed to each call."),
        )
        .with_field(StructField::from(("greet", greet)).with_comment(" Greets the name."));

    let return_error = || -> IfStatement {
        IfStatement::from("status != PP_OK")
            .with_success_statements(Block::default().with_semi("return status"))
    };
    let greet_call: Block = Block::default()
        .with_semi("greet_request_t greet_request")
        .with_statement(VarInit::from((
            ("status", "pp_status_t"),
            Literal::from("greet_request_decode(request, &greet_request)"),
        )))
        .with_statement(return_error())
        .with_semi("greet_response_t greet_response")
        .with_semi("status = service->greet(service->context, &greet_request, &greet_response)")
        .with_statement(return_error())
        .with_semi("greet_response_encode_to(&greet_response, response)")
        .with_semi("return PP_OK");
    let route: Function = Function::from(
        Signature::from("greeter_route")
            .with_result("pp_status_t")
            .with_param(("service", "const greeter_t *"))
            .with_param(("call", "const char *"))
            .with_param(("request", "pp_bytes_t"))
            .with_param(("response", "pp_buf_t *")),
    )
    .with_comment(" Routes the encoded `request` to the `call` of the greeter.")
    .with_statement(
        IfStatement::from("strcmp(call, \"greet\") == 0").with_success_statements(greet_call),
    )
    .with_semi("return PP_UNKNOWN_CALL");

    let code: String = Block::default()
        .with_statement(greeter)
        .with_empty_line()
        .with_statement(route)
        .to_code();

    let expected: &str = r#"/** A greeter. */
typedef struct greeter {
    /** The state that is passed to each call. */
    void *context;

    /** Greets the name. */
    pp_status_t (*greet)(void *context, const greet_request_t *request, greet_response_t *response);
} greeter_t;

/** Routes the encoded `request` to the `call` of the greeter. */
pp_status_t greeter_route(const greeter_t *service, const char *call, pp_bytes_t request, pp_buf_t *response) {
    if (strcmp(call, "greet") == 0) {
        greet_request_t greet_request;
        pp_status_t status = greet_request_decode(request, &greet_request);
        if (status != PP_OK) {
            return status;
        }
        greet_response_t greet_response;
        status = service->greet(service->context, &greet_request, &greet_response);
        if (status != PP_OK) {
            return status;
        }
        greet_response_encode_to(&greet_response, response);
        return PP_OK;
    }
    return PP_UNKNOWN_CALL;
}
"#;
    assert_eq!(code, expected);
}
